<?php
/** Authenticated administration for the public growth and private client workflows. */
declare(strict_types=1);
defined('CWP_BOOT') || exit;
function studio_admin_views(): array {return ['studio-clients'=>'Client workspace','studio-job'=>'Client project','studio-pipeline'=>'Sales pipeline','studio-content'=>'Sales content','studio-prices'=>'Estimator prices','studio-portfolio'=>'Portfolio previews','studio-history'=>'Content history','studio-upgrade'=>'Version & database'];}
function studio_revision_save(string $name,string $value,string $expected): void {
    require_admin();if(!in_array($name,['growth_intro','growth_faq','growth_packages','growth_prices','growth_package_0','growth_package_1','growth_package_2'],true))throw new InvalidArgumentException('Unknown content key.');
    db()->beginTransaction();try {
        // A permanent settings row provides a lock even for previously absent content.
        query('INSERT IGNORE INTO '.table('settings').' (name,value) VALUES (?,?)',[$name,'']);
        $old=(string)query('SELECT value FROM '.table('settings').' WHERE name=? FOR UPDATE',[$name])->fetchColumn();
        if(!hash_equals(hash('sha256',$old),$expected))throw new RuntimeException('Another session changed this content. Reload and review the newer version before saving.');
        query('INSERT INTO '.table('studio_revisions').' (setting_name,old_value,new_value,author_id,created_at) VALUES (?,?,?,?,?)',[$name,$old,$value,(int)$_SESSION['uid'],gmdate('Y-m-d H:i:s')]);
        save_setting($name,$value);db()->commit();
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function studio_admin_action(string $action,array $user): never {
    require_admin();check_csrf();$target='studio-clients';
    if($action==='studio_migrate'){if(posted('confirm',1)!=='1')throw new InvalidArgumentException('Confirm that you have a backup before updating.');studio_migrate();flash('Database update completed. Existing content was preserved.');redirect(admin_url('studio-upgrade'));}
    if(!studio_ready())throw new RuntimeException('Enable the workspace tables under Version & database first.');
    if($action==='studio_client'){
        $id=gint($_POST,'id',0,2147483647);$name=posted('name',120);$email=strtolower(posted('email',190));
        if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter the client name and a valid email.');
        if($id){if(!one('SELECT id FROM '.table('studio_clients').' WHERE id=?',[$id]))throw new InvalidArgumentException('Client not found.');query('UPDATE '.table('studio_clients').' SET name=?,email=?,active=?,auth_version=?,invite_hash=NULL,invite_expires=NULL WHERE id=?',[$name,$email,isset($_POST['active'])?1:0,bin2hex(random_bytes(16)),$id]);}
        else{query('INSERT INTO '.table('studio_clients').' (name,email,auth_version,created_at) VALUES (?,?,?,?)',[$name,$email,bin2hex(random_bytes(16)),gmdate('Y-m-d H:i:s')]);}
    }elseif($action==='studio_invite'){
        $id=gint($_POST,'id',1,2147483647);$c=one('SELECT id FROM '.table('studio_clients').' WHERE id=? AND active=1',[$id]);if(!$c)throw new InvalidArgumentException('Active client not found.');
        $_SESSION['studio_invite_link']=studio_new_invite($id);flash('New private invitation created. Share it directly with this client; it expires after 24 hours. No email was sent.');redirect(admin_url('studio-clients'));
    }elseif($action==='studio_job'){
        $id=gint($_POST,'id',0,2147483647);$client=gint($_POST,'client_id',1,2147483647);$title=posted('title',160);$stage=posted('stage',30);
        if(!one('SELECT id FROM '.table('studio_clients').' WHERE id=?',[$client])||$title===''||!isset(studio_stages()[$stage]))throw new InvalidArgumentException('Choose a client, title and valid stage.');
        $summary=posted('summary',10000);$milestones=posted('milestones',15000);$now=gmdate('Y-m-d H:i:s');
        if($id){$old=studio_job($id);if((int)$old['client_id']!==$client)throw new InvalidArgumentException('Project ownership cannot be transferred through this form. Create a separate project.');query('UPDATE '.table('studio_jobs').' SET title=?,summary=?,stage=?,milestones=?,updated_at=? WHERE id=?',[$title,$summary,$stage,$milestones,$now,$id]);}
        else{query('INSERT INTO '.table('studio_jobs').' (client_id,title,summary,stage,milestones,created_at,updated_at) VALUES (?,?,?,?,?,?,?)',[$client,$title,$summary,$stage,$milestones,$now,$now]);$id=(int)db()->lastInsertId();}
        log_event($action,'Project '.$id);flash('Project saved.');redirect(admin_url('studio-job',['id'=>$id]));
    }elseif(in_array($action,['studio_message','studio_publish','studio_upload','studio_invoice','studio_paid'],true)){
        $id=gint($_POST,'job_id',1,2147483647);studio_job($id);
        if($action==='studio_message'){$body=posted('body',5000);if(strlen($body)<2)throw new InvalidArgumentException('Write a message.');query('INSERT INTO '.table('studio_messages').' (job_id,author_type,author_id,body,created_at) VALUES (?,\'admin\',?,?,?)',[$id,$user['id'],$body,gmdate('Y-m-d H:i:s')]);}
        if($action==='studio_publish')studio_publish($id,posted('kind',20),posted('title',160),posted('body',30000),posted('preview_url',500));
        if($action==='studio_upload')studio_upload($id,'admin');
        if($action==='studio_invoice'){$amount=gcents(posted('amount',20));$title=posted('title',160);if($amount===null||$amount<=0||$title==='')throw new InvalidArgumentException('Enter an invoice title and positive amount.');query('INSERT INTO '.table('studio_invoices').' (job_id,reference,title,amount_cents,instructions,created_at) VALUES (?,?,?,?,?,?)',[$id,'INV-'.strtoupper(bin2hex(random_bytes(6))),$title,$amount,posted('instructions',6000),gmdate('Y-m-d H:i:s')]);}
        if($action==='studio_paid'){$invoice=gint($_POST,'invoice_id',1,2147483647);$note=posted('paid_note',500);if(strlen($note)<5||posted('confirm',1)!=='1')throw new InvalidArgumentException('Record a payment reference and confirm you independently verified receipt.');if(catalog_snapshot($invoice)){catalog_transition($id,$invoice,'paid',$note);}else{$s=query('UPDATE '.table('studio_invoices').' SET status=\'paid\',paid_note=?,paid_at=? WHERE id=? AND job_id=? AND status=\'issued\'',[$note,gmdate('Y-m-d H:i:s'),$invoice,$id]);if($s->rowCount()!==1)throw new InvalidArgumentException('Invoice not found or already recorded as paid.');}}
        log_event($action,'Project '.$id);flash('Project updated.');redirect(admin_url('studio-job',['id'=>$id]));
    }elseif($action==='studio_pipeline'){
        $id=gint($_POST,'id',1,2147483647);$stage=posted('status',20);if(!isset(studio_pipeline_stages()[$stage])||!one('SELECT id FROM '.table('leads').' WHERE id=?',[$id]))throw new InvalidArgumentException('Choose a valid inquiry and stage.');
        $follow=posted('follow_up',10);if($follow!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$follow)||date('Y-m-d',strtotime($follow))!==$follow))throw new InvalidArgumentException('Use a valid follow-up date.');
        db()->beginTransaction();try{query('UPDATE '.table('leads').' SET status=?,notes=? WHERE id=?',[$stage,posted('notes',10000),$id]);save_setting('growth_follow_'.$id,$follow);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}$target='studio-pipeline';
    }elseif($action==='studio_prices'){
        $r=['enabled'=>isset($_POST['enabled'])];foreach(growth_types()+['page'=>'Additional page','product'=>'Product']+growth_options() as $key=>$unused)$r[$key]=grange([gcents(posted($key.'_min',20)),gcents(posted($key.'_max',20))]);
        studio_revision_save('growth_prices',json_encode($r,JSON_THROW_ON_ERROR),posted('expected',64));$target='studio-prices';
    }elseif($action==='studio_content'){
        $name=posted('setting_name',100);$value=posted('value',24000);
        if(!in_array($name,['growth_intro','growth_faq','growth_packages'],true))throw new InvalidArgumentException('Unknown content section.');
        if($name==='growth_faq'||$name==='growth_packages'){$rows=json_decode($value,true,32,JSON_THROW_ON_ERROR);$width=$name==='growth_faq'?2:3;if(!is_array($rows)||!array_is_list($rows)||count($rows)<1||count($rows)>12)throw new InvalidArgumentException('Enter a JSON list containing between 1 and 12 items.');foreach($rows as $row){if(!is_array($row)||!array_is_list($row)||count($row)!==$width)throw new InvalidArgumentException('Each content item has '.$width.' text fields.');foreach($row as $text)if(!is_string($text)||strlen($text)>6000)throw new InvalidArgumentException('Use bounded text values.');}}
        studio_revision_save($name,$value,posted('expected',64));$target='studio-content';
    }elseif($action==='studio_restore_content'){
        $id=gint($_POST,'id',1,2147483647);$rev=one('SELECT * FROM '.table('studio_revisions').' WHERE id=?',[$id]);if(!$rev)throw new InvalidArgumentException('Revision not found.');if(posted('confirm',1)!=='1')throw new InvalidArgumentException('Confirm this deliberate restore.');studio_revision_save($rev['setting_name'],$rev['old_value'],posted('expected',64));$target='studio-history';
    }elseif($action==='studio_media'){
        $mediaId=upload_image('image');if(!$mediaId)throw new InvalidArgumentException('Choose a portfolio image.');$target='studio-portfolio';
    }elseif($action==='studio_portfolio'){
        $id=gint($_POST,'id',1,2147483647);if(!one('SELECT id FROM '.table('projects').' WHERE id=?',[$id]))throw new InvalidArgumentException('Portfolio project not found.');
        $v=['caption'=>posted('caption',500),'walkthrough'=>safe_url(posted('walkthrough',500),true)];foreach(['desktop','mobile','before'] as $key){$value=posted($key,32);if($value!==''&&(!preg_match('/^[a-f0-9]{32}$/D',$value)||!one('SELECT id FROM '.table('media').' WHERE id=?',[$value])))throw new InvalidArgumentException('Choose an uploaded image from the media library.');$v[$key]=$value;}
        save_setting('growth_portfolio_'.$id,json_encode($v,JSON_THROW_ON_ERROR));$target='studio-portfolio';
    }else throw new InvalidArgumentException('Unknown studio action.');
    log_event($action);flash('Saved.');redirect(admin_url($target));
}
function studio_pipeline_stages(): array {return ['new'=>'New inquiry','contacted'=>'Consultation','qualified'=>'Qualified','proposal'=>'Proposal sent','won'=>'Won','closed'=>'Not proceeding','spam'=>'Spam'];}
function studio_hidden(string $name,mixed $value): void {echo '<input type="hidden" name="'.esc($name).'" value="'.esc($value).'">';}
function studio_admin_render(string $view,array $user,string $error): void {
    if($view==='studio-job'&&isset($_GET['file']))studio_download(is_string($_GET['file'])?$_GET['file']:'',null);
    admin_head(studio_admin_views()[$view],$view,$user);if($error)echo '<div class="notice error" role="alert">'.esc($error).'</div>';
    if(!studio_ready()&&$view!=='studio-upgrade'){echo '<div class="notice warning">The new database tables are not enabled. Your existing website is unchanged. Open <a href="'.esc(admin_url('studio-upgrade')).'">Version &amp; database</a> to apply the additive update.</div>';admin_foot();return;}
    if($view==='studio-upgrade'){ ?>
      <section class="workspace-card"><span class="eyebrow">ONE EXPLICIT UPDATE</span><h2>Application <?=esc(CWP_VERSION)?></h2><p>Workspace schema: <?=studio_ready()?'current':'not enabled / needs update'?>. This creates or verifies the client-workspace and content-history tables. It does not replace existing website tables or reset your settings.</p><p>Back up your files and database before applying an update. This is a database update, not an application-file updater or a complete backup service.</p><form method="post"><?php admin_action('studio_migrate');admin_check('confirm','I have a current database and file backup.',false);?><button class="btn gold">Verify & apply database update →</button></form></section>
    <?php }elseif($view==='studio-clients'){
      if(isset($_SESSION['studio_invite_link'])){$link=$_SESSION['studio_invite_link'];unset($_SESSION['studio_invite_link']);echo '<div class="notice info">Private invitation (displayed once): <a rel="noreferrer" href="'.esc($link).'">'.esc($link).'</a></div>';}
      ?><div class="workspace-grid"><section class="workspace-card"><h2>Add a client</h2><form method="post"><?php admin_action('studio_client');studio_hidden('id',0);admin_input('name','Name','','text','required maxlength="120"');admin_input('email','Email','','email','required maxlength="190"');?><button class="btn gold">Create client</button></form></section><section class="workspace-card"><h2>Create a project</h2><form method="post"><?php admin_action('studio_job');studio_hidden('id',0);admin_select('client_id','Client',array_column(all('SELECT id,name FROM '.table('studio_clients').' ORDER BY name'),'name','id'),'');admin_input('title','Project title','','text','required maxlength="160"');admin_select('stage','Stage',studio_stages(),'discovery');admin_textarea('summary','Summary');admin_textarea('milestones','Milestones');?><button class="btn gold">Create project</button></form></section></div><h2>Clients</h2><div class="workspace-grid"><?php foreach(all('SELECT * FROM '.table('studio_clients').' ORDER BY id DESC LIMIT 100') as $c):?><section class="workspace-card"><form method="post"><?php admin_action('studio_client');studio_hidden('id',$c['id']);admin_input('name','Name',$c['name']);admin_input('email','Email',$c['email'],'email');admin_check('active','Active account',$c['active']);?><button class="btn outline">Save / revoke old sessions</button></form><form method="post"><?php admin_action('studio_invite');studio_hidden('id',$c['id']);?><button class="btn gold">Create private invitation</button></form><?php if((int)$c['active']===1)support_open_form((int)$c['id']);foreach(all('SELECT id,title,stage FROM '.table('studio_jobs').' WHERE client_id=? ORDER BY id DESC',[$c['id']]) as $j)echo '<p><a href="'.esc(admin_url('studio-job',['id'=>$j['id']])).'">'.esc($j['title']).' →</a> · '.esc($j['stage']).'</p>';?></section><?php endforeach;?></div><?php
    }elseif($view==='studio-job'){
      $id=gint($_GET,'id',1,2147483647);$j=studio_job($id);?><section class="workspace-card"><form method="post"><?php admin_action('studio_job');studio_hidden('id',$id);studio_hidden('client_id',$j['client_id']);admin_input('title','Project title',$j['title']);admin_select('stage','Stage',studio_stages(),$j['stage']);admin_textarea('summary','Summary',$j['summary']);admin_textarea('milestones','Milestones',$j['milestones']);?><button class="btn gold">Save project</button></form></section><div class="workspace-grid"><section class="workspace-card"><h2>Publish a design or proposal version</h2><p>Published versions are immutable. To revise, publish a new version; pending older versions cannot be approved.</p><form method="post"><?php admin_action('studio_publish');studio_hidden('job_id',$id);admin_select('kind','Review type',['design'=>'Design','proposal'=>'Proposal'],'design');admin_input('title','Version title','','text','required');admin_textarea('body','Design details / proposal scope','',8,30000);admin_input('preview_url','HTTPS preview link (optional)','','url');?><button class="btn gold">Publish new version</button></form><?php foreach(all('SELECT * FROM '.table('studio_versions').' WHERE job_id=? ORDER BY id DESC',[$id]) as $v)echo '<div class="workspace-version"><strong>'.esc($v['kind'].' v'.$v['version_no'].' · '.$v['title']).'</strong><p>'.esc($v['decision']).' · '.esc($v['feedback']).'</p></div>';?></section><section class="workspace-card"><h2>Conversation</h2><?php foreach(all('SELECT * FROM '.table('studio_messages').' WHERE job_id=? ORDER BY id DESC LIMIT 100',[$id]) as $m)echo '<div class="workspace-message"><small>'.esc($m['author_type'].' · '.$m['created_at']).' UTC</small>'.esc($m['body']).'</div>';?><form method="post"><?php admin_action('studio_message');studio_hidden('job_id',$id);admin_textarea('body','Message');?><button class="btn gold">Save message to workspace</button></form><h3>Private files</h3><?php foreach(all('SELECT * FROM '.table('studio_files').' WHERE job_id=?',[$id]) as $f)echo '<p><a href="'.esc(admin_url('studio-job',['id'=>$id,'file'=>$f['id']])).'">'.esc($f['original_name']).' ↓</a></p>';?><form method="post" enctype="multipart/form-data"><?php admin_action('studio_upload');studio_hidden('job_id',$id);?><label>PDF, PNG or JPEG, up to 8 MB<input name="document" type="file" required accept=".pdf,.png,.jpg,.jpeg"></label><button class="btn outline">Upload privately</button></form></section></div><section class="workspace-card"><h2>Manual invoices</h2><?php catalog_project_entry($id);?><p>No card charging or recurring billing is enabled. Mark paid only after independently verifying payment.</p><form method="post"><?php admin_action('studio_invoice');studio_hidden('job_id',$id);admin_input('title','Invoice title');admin_input('amount','Amount in USD (for example 125.00)');admin_textarea('instructions','Payment instructions');?><button class="btn gold">Issue invoice</button></form><?php foreach(all('SELECT * FROM '.table('studio_invoices').' WHERE job_id=? ORDER BY id DESC',[$id]) as $inv):?><div class="workspace-version"><h3><?=esc($inv['reference'].' · '.$inv['title'])?></h3><p>$<?=gmoney((int)$inv['amount_cents'])?> USD · <?=esc($inv['status'])?></p><?php catalog_invoice_view($inv);catalog_void_form($inv);if($inv['status']==='issued'&&(!catalog_snapshot((int)$inv['id'])||staff_can('catalog.manage'))):?><form method="post"><?php admin_action('studio_paid');studio_hidden('job_id',$id);studio_hidden('invoice_id',$inv['id']);admin_input('paid_note','Verified payment reference');admin_check('confirm','I independently verified that payment was received.',false);?><button class="btn outline">Record received payment</button></form><?php endif;?></div><?php endforeach;?></section><?php
    }elseif($view==='studio-pipeline'){
      $rows=all('SELECT * FROM '.table('leads').' ORDER BY id DESC LIMIT 300');?><div class="pipeline"><?php foreach(studio_pipeline_stages() as $key=>$label):?><section><h3><?=esc($label)?></h3><?php foreach($rows as $lead)if($lead['status']===$key):?><article><a href="<?=esc(admin_url('lead',['id'=>$lead['id']]))?>"><strong><?=esc($lead['name'])?></strong></a><p><?=esc($lead['service'])?></p><form method="post"><?php admin_action('studio_pipeline');studio_hidden('id',$lead['id']);admin_select('status','Stage',studio_pipeline_stages(),$lead['status']);admin_input('follow_up','Next follow-up',setting('growth_follow_'.$lead['id']),'date');admin_textarea('notes','Notes',$lead['notes'],3,10000);?><button class="btn outline small">Save</button></form></article><?php endif;?></section><?php endforeach;?></div><p>Showing up to the latest 300 inquiries. The original inquiry inbox retains search and export.</p><?php
    }elseif($view==='studio-prices'){
      $r=growth_rules();?><section class="workspace-card"><p>All prices start unpublished. Base prices include five pages. Additional pages and each product are added using these ranges. Blank rules and custom integrations require a consultation.</p><form method="post"><?php admin_action('studio_prices');studio_hidden('expected',hash('sha256',setting('growth_prices')));admin_check('enabled','Publish these estimate ranges',($r['enabled']??false)===true);foreach(growth_types()+['page'=>'Each additional page','product'=>'Each product']+growth_options() as $k=>$label):?><fieldset><legend><?=esc($label)?></legend><div class="field-grid"><?php admin_input($k.'_min','Minimum USD',gmoney($r[$k][0]??null));admin_input($k.'_max','Maximum USD',gmoney($r[$k][1]??null));?></div></fieldset><?php endforeach;?><button class="btn gold">Save price rules</button></form></section><?php
    }elseif($view==='studio-content'){
      foreach(['growth_intro'=>['Homepage introduction','Bring your brand to life with purposeful design and development.'],'growth_faq'=>['FAQ items: JSON question/answer pairs',json_encode(growth_faq(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)],'growth_packages'=>['Package items: JSON title/summary/inclusions',json_encode(growth_packages(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)]] as $name=>[$label,$fallback]):?><section class="workspace-card"><form method="post"><?php admin_action('studio_content');studio_hidden('setting_name',$name);studio_hidden('expected',hash('sha256',setting($name)));admin_textarea('value',$label,setting($name,$fallback),10,24000);?><button class="btn gold">Save this section</button></form></section><?php endforeach;
    }elseif($view==='studio-history'){
      ?><p>Restoring creates a new recorded revision. Current content is checked for changes before a restore can apply.</p><?php foreach(all('SELECT * FROM '.table('studio_revisions').' ORDER BY id DESC LIMIT 100') as $r):?><section class="workspace-card"><h3><?=esc($r['setting_name'])?> · <?=esc($r['created_at'])?> UTC</h3><details><summary>Compare saved values</summary><h4>Before</h4><pre class="history-text"><?=esc($r['old_value'])?></pre><h4>After</h4><pre class="history-text"><?=esc($r['new_value'])?></pre></details><form method="post"><?php admin_action('studio_restore_content');studio_hidden('id',$r['id']);studio_hidden('expected',hash('sha256',setting($r['setting_name'])));admin_check('confirm','Restore the Before value as a new revision.',false);?><button class="btn outline">Restore this value</button></form></section><?php endforeach;
    }elseif($view==='studio-portfolio'){
      $media=[''=>'Not set']+array_column(all('SELECT id,original_name FROM '.table('media').' ORDER BY created_at DESC'),'original_name','id');?><section class="workspace-card"><h2>Upload a public portfolio capture</h2><form method="post" enctype="multipart/form-data"><?php admin_action('studio_media');?><label>PNG, JPEG or WebP, up to 6 MB<input type="file" name="image" accept=".png,.jpg,.jpeg,.webp" required></label><button class="btn gold">Upload capture</button></form><p>These images are public portfolio media. Use the private client workspace for client documents.</p></section><p>Upload images above, then choose genuine desktop/mobile/before captures here. Leave missing views unset rather than mislabeling a desktop screenshot.</p><?php foreach(all('SELECT id,title FROM '.table('projects').' ORDER BY id DESC') as $p):$g=gjson('growth_portfolio_'.$p['id']);?><section class="workspace-card"><h2><?=esc($p['title'])?></h2><form method="post"><?php admin_action('studio_portfolio');studio_hidden('id',$p['id']);foreach(['desktop','mobile','before'] as $key)admin_select($key,ucfirst($key).' capture',$media,$g[$key]??'');admin_input('walkthrough','HTTPS walkthrough link',$g['walkthrough']??'','url');admin_input('caption','Capture description / date',$g['caption']??'');?><button class="btn gold">Save project previews</button></form></section><?php endforeach;
    }
    admin_foot();
}
